export interface Env extends Cloudflare.Env {
	// SCRIBASE_URL and OWNER_EMAIL are plain `vars` in wrangler.jsonc, so
	// `Cloudflare.Env` (generated by `wrangler types`) already declares them.
	/** The Scribase project's public anon/publishable key (safe to ship; required by GoTrue as `apikey`). Set via `wrangler secret put` until provisioning is done, then may move to `vars`. */
	SCRIBASE_ANON_KEY: string;
}
